@njit(nogil=True, fastmath=True, cache=True)
def _sample_negatives(rng_state, noise_cumsum, neg_samples):
    """Sample `neg_samples` words from noise_cumsum using inversion sampling.
    Returns an array of negative word indices.
    """
    vocab_size = len(noise_cumsum)
    out = np.empty(neg_samples, dtype=np.int32)
    for i in range(neg_samples):
        r = np.random.random_sample()
        for j in range(vocab_size):
            if noise_cumsum[j] >= r:
                out[i] = j
                break
    return out

